--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `product_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `brand` varchar(255) DEFAULT NULL,
  `model` varchar(255) DEFAULT NULL,
  `product_name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `sku` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `specifications` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`specifications`)),
  `price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `sale_price` decimal(12,2) DEFAULT NULL,
  `compare_price` decimal(12,2) DEFAULT NULL,
  `average_rating` decimal(3,1) NOT NULL DEFAULT 0.0,
  `total_reviews` int(10) unsigned NOT NULL DEFAULT 0,
  `cost_price` decimal(12,2) DEFAULT NULL,
  `stock_quantity` int(11) NOT NULL DEFAULT 0,
  `low_stock_threshold` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','inactive','out_of_stock') NOT NULL DEFAULT 'active',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_new` tinyint(1) NOT NULL DEFAULT 0,
  `is_bestseller` tinyint(1) NOT NULL DEFAULT 0,
  `view_count` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`product_id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_category_id_foreign` (`category_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,2,'AULA','AULA','WIRELESS KEYBOARD (คีย์บอร์ดไร้สาย) LEOBOG AMG65 PURPLE LIGHT SILENT SWITCH','wireless-keyboard-leobog-amg65-purple-light-silent-switch','KB010101','การเชื่อมต่อ Tri-mode Wireless2.4g, Bluetooth , Wired Type c\r\nDual Screen (หน้าจอ Dot Matrix LED สามารถปรับแต่งภาพได้และมีจอ TFT อีก 1 จอทางด้านขวาสามาร\r\nเวลา หรือใส่ GIF)\r\nสวิตซ์ Light Silent Linear Switch (Pre lube) เสียงเงียบ\r\nGasket structure, hot-swappable 3-5PIN Switch\r\nม็อดโฟม 5 ชั้น Five-Layered Sound-Absorbing Padding\r\nPC Material Positioning Plat ฟีลกดนุ่มนวลรองรับแรงกระแทก\r\nLight Mode Full RGB (Music Rhythm Available through software)\r\nซอฟแวร์ไดรฟ์เวอร์ ปรับตั้งค่าคีย์บอร์ด ปรับโหมดไฟ ปรับมาโครแบบอัจฉริยะ\r\nLayout 65% 67 Keys\r\nKeycap PBT Dye Sub\r\nBattery 8,000 mAh Rechargeable battery\r\nSize 325.18x 143.38 x 44.28mm\r\nFull Anti-Ghosting\r\nWeight: 1020 G (excluding cable/receiver)\r\nSupport System: Windows | Mac | iOS | Android\r\nรับประกันสินค้า 2 ปี',NULL,3999.00,3500.00,NULL,5.0,1,NULL,19,0,'active',1,1,0,0,0,'2025-11-22 02:51:32','2025-11-22 07:58:08'),(2,3,'AULA','AULA','WIRELESS MOUSE (เมาส์ไร้สาย) AULA SC620 BLACK CONTOUR TRI-MODE PAW3311','wireless-mouse-aula-sc620-black-contour-tri-mode-paw3311','MG010101','3IN1 GAMING MOUSE AULA SC620 (BLACK) CT\r\nเชื่อมต่อ 3ระบบ type C / Wireless 2.4GHz / Bluetooth 2 อุปกรณ์\r\nLightweight Design น้ำหนักเบาและโชว์โครงสร้างด้านในเมาส์\r\nน้ำหนัก 67 กรัม\r\n8 ปุ่มกด 6Level ปรับความละเอียดสูงสุด 12000 DPI และปรับละเอียด Custom ในซอฟแวร์\r\nFire Button ใช้เพิ่มความแม่นยำในการเล่นเกมส์ & ทำงานออฟฟิศ ปรับแต่งฟังก์ชันก์ได้\r\nPoling Rate 1000Hz\r\nปรแกรม Macro อัจฉริยะ ปรับแต่งโหมดไฟ,โหมดการใช้งาน,ปรับ DPI และ Macro เมาส์+คีย์บอร์ด\r\nฟังชันก์มาโคร Loop until stop pressing,Loop until any click,Looptime\r\nOptical Sensor PIXART PAW3311\r\nMain switch Huanyu รองรับการกด 20 ล้านครั้ง\r\nRGB Lighting Effects ปรับได้ในโปรแกรม Driver\r\nออกแบบทรงเมาส์มือขวา ตามหลักสรีระศาสตร์\r\nรองรับรูปแบบการจับเมาส์ Claw Grip / Finger Grip / Palm Grip\r\nRechargeable Li-battery 400mAh\r\nสายUSB to Type-C หุ้มผ้า น้ำหนักเบา ยาว 1.5 เมตร\r\nรองรับระบบ Windows XP/7/8/10/11/Vista/Mac/Android/ios\r\nขนาด (ย)122 x (ก)64 x (ส)40 มม.\r\nรับประกัน 2 ปี',NULL,999.00,950.00,NULL,0.0,0,NULL,19,0,'active',1,1,0,0,0,'2025-11-22 08:09:00','2025-11-23 20:55:23'),(3,4,'AULA','AULA','HEADSET (หูฟัง) AULA S501 USB','headset-aula-s501-usb','HDS010101','Gaming Headset RGB with USB\r\nลำโพงขนาด 50มม.* ที่คาดศีรษะ แสงไฟ RGB\r\nฟองน้ำซับเสียงบุด้วยหนัง PU\r\nความต้านทานลำโพง 20โอมห์\r\nความถี่ 20Hz-20kHz /ความดังเสียง 117 ±3dB\r\nความไวของเสียงไมค์โคโฟน-38dB ±3dB\r\nไมค์โครโฟนมีระบบตัดเสียงรบกวน ปุ่มปรับความดังเสียงข้าง\r\nเชื่อมต่อ USB สายยาว 2.1 เมตร\r\nน้ำหนัก 325 กรัม * ขนาดสินค้า 205 *90* 220 มม.',NULL,999.00,980.00,NULL,0.0,0,NULL,20,0,'active',1,1,0,0,0,'2025-11-22 08:31:22','2025-11-22 08:33:41'),(4,5,'Lenovo','Lenovo','LECOO DS104 SPEAKER USB','lecoo-ds104-speaker-usb','SPK010101','Wired Speaker RGB USB 2.0 Powered by Lenovo\r\nUSB-Powered (5V) อินพุตเสียง AUX 3.5mm\r\nกำลังขับ 6W 2*3W (RMS)\r\nเอฟเฟกต์แสง RGB และปุ่มควบคุมระดับเสียง\r\nความถี่ที่สอดคล้องกัน 80Hz-20KGz\r\nอัตราส่วนสัญญาณต่อสัญญาณรบกวน >80Db\r\nPlug and play & การเล่นเกมที่เข้ากันได้แบบสากล\r\nขนาด 78 X 100 X 174 (WxDxH) มม.\r\nน้ำหนัก 640กรัม',NULL,700.00,590.00,NULL,0.0,0,NULL,19,0,'active',1,1,0,0,0,'2025-11-22 08:33:07','2025-11-28 01:42:49'),(5,2,'AULA','AULA','AULA S2022 BLACK HOTSWAP MECHANICAL GAMING KEYBOARD','aula-s2022-black-hotswap-mechanical-gaming-keyboard','KB020202','คีย์บอร์ดเกมมิ่ง WIND Mechanical 104\r\nHot Swap เปลี่ยนสวิตซ์\r\nตัวเรือนพลาสติก ABS ด้านบน / แป้น FN MultiMedia\r\nBlue Switch รองรับการกด 60ล้านครั้ง\r\nAnti-ghosting 26 ปุ่ม สายถักผ้า1.60 ม. เชื่อมต่อ USB 2.0\r\nสายถักผ้า ยาว 1.60 เมตร เชื่อมต่อ USB 2.0\r\nขนาดผลิตภัณฑ์ L435 x W125 x H38 มม\r\nน้ำหนักผลิตภัณฑ์ 670กรัม\r\nรับประกัน 2 ปี ตามเงื่อนไขบริษัท',NULL,1200.00,1099.00,NULL,0.0,0,NULL,20,0,'active',1,1,0,0,0,'2025-11-22 08:36:27','2025-11-22 08:36:27'),(6,2,'AULA','AULA','AULA F2058 MECHANICAL GAMING KEYBOARD','aula-f2058-mechanical-gaming-keyboard','KB030303','Wired Mechanical Gaming Keyboard\r\nคีย์บอร์ดเกมมิ่ง WIND Mechanical 109key\r\nกล่องด้านบนทำด้วยโลหะพร้อมแผ่นใส่ในการเดินทาง\r\n5 ปุ่มลัด MultiMedia / FN MultiMedia key\r\nBlue Switch รองรับการกด 60 ล้านครั้ง\r\nN-Key Anti-ghosting มาโครที่ตั้งโปรแกรมได้อย่างเต็มที่\r\nที่วางข้อมือแม่เหล็กตามหลักสรีรศาสตร์\r\nสายถักผ้า ยาว 1.60 เมตร เชื่อมต่อ USB 2.0\r\nขนาดผลิตภัณฑ์ L435 x W194 x H36 มม\r\nน้ำหนักผลิตภัณฑ์ 920กรัม\r\nรับประกัน 2 ปี ตามเงื่อนไขบริษัท',NULL,1500.00,1400.00,NULL,0.0,0,NULL,20,0,'active',1,1,0,0,0,'2025-11-22 08:38:15','2025-11-25 21:58:32'),(7,2,'AULA','AULA','AULA F3030 MECHANICAL GAMING KEYBOARD','aula-f3030-mechanical-gaming-keyboard','KB040404','ปุ่ม Blue Switch 109 คีย์ รองรับการกด 60 ล้านครั้ง\r\nเคสอลูมิเนียม\r\nเอฟเฟกต์แสงไฟ 20 โหมด\r\nซอฟต์แวร์ปรับตั้งค่าปุ่ม / 1 โปรไฟล์ / เอฟเฟกต์ไฟ / Macro\r\nฟังก์ชัน FN ปุ่มลัด Multimedia / เพิ่ม-ลดแสงไฟ\r\nสกอร์บาร์ เพิ่ม/ลดเสียง เพลงก่อนหน้า/ถัดไป\r\nปุ่มลัด Multimedia 5 ปุ่ม\r\nกดพร้อมกันได้ 26 ปุ่ม (Anti-ghosting)\r\nสายถัดผ้า ยาว 1.60 เมตร เชื่อมต่อ USB 2.0',NULL,999.00,950.00,NULL,0.0,0,NULL,19,0,'active',1,1,0,0,0,'2025-11-22 08:41:55','2025-11-28 01:49:10'),(8,3,'AULA','AULA','MOUSE (เมาส์) AULA F813 PRO GAMING MOUSE','mouse-aula-f813-pro-gaming-mouse','MG020202','ความละเอียดสูงสุด 12400 DPI\r\n7ปุ่ม 6Level 12400/7600/5600/3200/2000/1000 DPI\r\nปรับPoling Rateได้4ระดับ 125/250/500/1000Hz\r\nโปรแกรมไดรฟ์เวอร์รองรับ WINDOWS\r\nฟังก์ชันโปรแกรมมาโคร Repeat the specified number orpress any key to end\r\nฟังก์ชันโปรแกรมมาโคร Repeat until you press any key to end\r\nฟังก์ชันโปรแกรมมาโคร Repeat until the key release\r\nด้านบนแสงไฟ RGB\r\nสายหุ้มผ้า ยาว 1.5 เมตร\r\nเชื่อมต่อ USB2.0\r\nรองรับระบบ Windows XP/7/8/10/11/Vista/Mac.\r\nขนาดผลิตภัณฑ์ L123 x W67 x H38 มม.\r\nน้ำหนัก 59กรัม\r\nรับประกัน 2 ปี',NULL,1000.00,980.00,NULL,0.0,0,NULL,20,0,'active',1,1,0,0,0,'2025-11-22 08:43:57','20